    ConnectAdditionalRequest,
    isConnectUrl,
    isWalletInfoCurrentlyEmbedded,
    ITonConnect,
    OptionalTraceable,
    Traceable,
    UUIDv7,
    WalletInfoCurrentlyEmbedded
} from '@tonconnect/sdk';
