    ignoreErrors?: boolean;
    signal?: AbortSignal | null;
}>;

type WaitSendTransactionOptions = Traceable<{
    transaction: SendTransactionRequest;
    signal: AbortSignal;
}>;

type WaitSignDataOptions = Traceable<{
    data: SignDataPayload;
    signal: AbortSignal;
}>;
